        observer.email_received: {"id":"evt_sample","eventType":"observer.email_received","payload":{"id":"msg_abc","from":"alice@example.com","to":"me@example.com","subject":"Re: launch","date":"2026-05-26T09:00:00Z","snippet":"Hey, can you review the deck before our 2pm? It's blocking the release...","labels":["INBOX","IMPORTANT"]},"timestamp":0}
        observer.calendar_event_starting: {"id":"evt_sample","eventType":"observer.calendar_event_starting","payload":{"summary":"Standup","start":"2026-05-07T15:00:00Z"},"timestamp":0}
        observer.process_started: {"id":"evt_sample","eventType":"observer.process_started","payload":{"pid":1234,"name":"node"},"timestamp":0}
        observer.process_stopped: {"id":"evt_sample","eventType":"observer.process_stopped","payload":{"pid":1234,"name":"node"},"timestamp":0}
        observer.notification_received: {"id":"evt_sample","eventType":"observer.notification_received","payload":{"app":"Slack","title":"Alice","body":"Message from Alice","urgency":"normal"},"timestamp":0}
        commitment.due_soon: {"id":"evt_sample","eventType":"commitment.due_soon","payload":{"id":"c_abc","what":"Follow up with vendor","when_due":1710000000000},"timestamp":0}
        commitment.overdue: {"id":"evt_sample","eventType":"commitment.overdue","payload":{"id":"c_abc","what":"Follow up with vendor","when_due":1710000000000},"timestamp":0}
        awareness.context_changed: {"id":"evt_sample","eventType":"awareness.context_changed","payload":{"app":"VS Code","project":"jarvis"},"timestamp":0}
        awareness.error_detected: {"id":"evt_sample","eventType":"awareness.error_detected","payload":{"app":"Terminal","excerpt":"fatal: not a git repository"},"timestamp":0}
        awareness.stuck_detected: {"id":"evt_sample","eventType":"awareness.stuck_detected","payload":{"app":"VS Code","windowTitle":"config.ts","durationMs":600000},"timestamp":0}
        awareness.struggle_detected: {"id":"evt_sample","eventType":"awareness.struggle_detected","payload":{"app":"VS Code","signal":"repeated_undo"},"timestamp":0}
